  3	import com.pousadamarealta.model.Message;
  4	import com.pousadamarealta.model.MessageChannel;
  5	import com.pousadamarealta.model.MessageStatus;
  6	
  7	import java.util.ArrayList;
  8	import java.util.List;
  9	import java.util.concurrent.atomic.AtomicLong;
 10	
 11	public class MessageService {
 12	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
 13	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
 14	
 15	    private final List<Message> messages = new ArrayList<>();
 16	    private final AtomicLong messageIdCounter = new AtomicLong(1);
 17	    private final boolean testMode;
 18	
 19	    public MessageService() {
 20	        this.testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 21	    }
 22	
 23	    public void sendEmail(String to, String subject, String body) {
 24	        if (!isValidEmail(to)) {
 25	            Message blockedMessage = new Message(
 26	                messageIdCounter.getAndIncrement(),
 27	                MessageChannel.EMAIL,
 28	                to,
 29	                subject,
 30	                body,
 31	                MessageStatus.BLOCKED
 32	            );
 33	            messages.add(blockedMessage);
 34	            return;
 35	        }
 36	
 37	        String actualTo = to;
 38	        String actualSubject = subject;
 39	        String actualBody = body;
 40	
 41	        if (testMode) {
 42	            actualTo = TEST_EMAIL;
 43	            actualSubject = "[TESTE] " + subject;
 44	            actualBody = "Destinatário original: " + to + "\n" + body;
 45	        }
 46	
 47	        Message sentMessage = new Message(
 48	            messageIdCounter.getAndIncrement(),
 49	            MessageChannel.EMAIL,
 50	            actualTo,
 51	            actualSubject,
 52	            actualBody,
 53	            MessageStatus.SENT
 54	        );
 55	        messages.add(sentMessage);
 56	
 57	        if (!testMode) {
 58	            Message archiveCopy = new Message(
 59	                messageIdCounter.getAndIncrement(),
 60	                MessageChannel.EMAIL,
 61	                ARCHIVE_EMAIL,
 62	                "[Cópia] " + subject,
 63	                body,
 64	                MessageStatus.SENT
 65	            );
 66	            messages.add(archiveCopy);
 67	        }
 68	    }
 69	
 70	    private boolean isValidEmail(String email) {
 71	        if (email == null || email.isEmpty()) {
 72	            return false;
 73	        }
 74	
 75	        int atIndex = email.indexOf('@');
 76	        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
 77	            return false;
 78	        }
 79	
 80	        String domain = email.substring(atIndex + 1);
 81	        if (domain.isEmpty() || !domain.contains(".")) {
 82	            return false;
 83	        }
 84	
 85	        int lastDotIndex = domain.lastIndexOf('.');
 86	        if (lastDotIndex == 0 || lastDotIndex == domain.length() - 1) {
 87	            return false;
 88	        }
 89	
 90	        return true;
 91	    }
 92	
 93	    public List<Message> getAllMessages() {
 94	        return new ArrayList<>(messages);
 95	    }
 96	}
