114	import io.javalin.json.JavalinJackson;
115	
116	public class Application {
117	
118	    public static void main(String[] args) {
119	        int port = getPort();
120	
121	        MessageService messageService = new MessageService();
122	        RoomService roomService = new RoomService();
123	        ReservationService reservationService = new ReservationService(roomService, messageService);
124	        ReportService reportService = new ReportService(reservationService, roomService);
125	
126	        RoomController roomController = new RoomController(roomService);
127	        ReservationController reservationController = new ReservationController(reservationService, roomService);
128	        MessageController messageController = new MessageController(messageService);
129	        ReportController reportController = new ReportController(reportService);
130	
131	        ObjectMapper objectMapper = new ObjectMapper();
132	        objectMapper.registerModule(new JavaTimeModule());
133	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
134	
135	        Javalin app = Javalin.create(config -> {
136	            config.jsonMapper(new JavalinJackson(objectMapper, true));
137	        });
138	
139	        app.get("/rooms", roomController::getRooms);
140	
141	        app.post("/reservations", reservationController::createReservation);
142	        app.get("/reservations/{id}", reservationController::getReservation);
143	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
144	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
145	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
146	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
147	        app.get("/reservations/{id}/document", reservationController::getDocument);
148	
149	        app.get("/messages", messageController::getMessages);
150	
151	        app.get("/reports/occupancy", reportController::getOccupancyReport);
152	        app.get("/reports/revenue", reportController::getRevenueReport);
153	
154	        app.exception(ApiException.class, (e, ctx) -> {
155	            ctx.status(e.getStatusCode());
156	            ctx.json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
157	        });
158	
159	        app.exception(BadRequestResponse.class, (e, ctx) -> {
160	            ctx.status(400);
161	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Corpo da requisição inválido"));
162	        });
163	
164	        app.exception(Exception.class, (e, ctx) -> {
165	            e.printStackTrace();
166	            ctx.status(500);
167	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Erro interno do servidor"));
168	        });
169	
170	        app.start(port);
171	
172	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
173	        System.out.println("Servidor rodando na porta " + port);
174	    }
175	
176	    private static int getPort() {
177	        String portEnv = System.getenv("PORT");
178	        if (portEnv != null && !portEnv.isEmpty()) {
179	            try {
180	                return Integer.parseInt(portEnv);
181	            } catch (NumberFormatException e) {
182	                System.err.println("PORT inválida, usando porta padrão 7070");
183	            }
184	        }
185	        return 7070;
186	    }
187	}
