    1	package com.pousadamarealta.service;
    2	
    3	import com.pousadamarealta.model.*;
    4	import com.pousadamarealta.util.FormatUtil;
    5	import com.pousadamarealta.util.PricingUtil;
    6	
    7	import java.math.BigDecimal;
    8	import java.time.LocalDate;
    9	import java.util.*;
   10	import java.util.concurrent.atomic.AtomicLong;
   11	import java.util.stream.Collectors;
   12	
   13	public class ReservationService {
   14	    private final Map<Long, Reservation> reservations = new LinkedHashMap<>();
   15	    private final AtomicLong reservationIdCounter = new AtomicLong(1);
   16	    private final RoomService roomService;
   17	    private final MessageService messageService;
   18	
   19	    public ReservationService(RoomService roomService, MessageService messageService) {
   20	        this.roomService = roomService;
   21	        this.messageService = messageService;
   22	    }
   23	
   24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
   25	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
   26	        Room room = roomService.getRoom(roomNumber);
   27	
   28	        if (guests < 1) {
   29	            throw ApiException.invalidRequest("Número de hóspedes deve ser pelo menos 1");
   30	        }
   31	
   32	        if (guests > room.getCapacity()) {
   33	            throw ApiException.capacityExceeded();
   34	        }
   35	
   36	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
   37	            throw ApiException.invalidRequest("Data de saída deve ser após a data de entrada");
   38	        }
   39	
   40	        if (!isRoomAvailable(roomNumber, checkIn, checkOut, null)) {
   41	            throw ApiException.roomUnavailable();
   42	        }
   43	
   44	        int nights = (int) checkIn.until(checkOut).getDays();
   45	
   46	        BigDecimal subtotal = BigDecimal.ZERO;
   47	        LocalDate currentNight = checkIn;
   48	        while (currentNight.isBefore(checkOut)) {
   49	            BigDecimal nightPrice = PricingUtil.calculateNightlyPrice(room.getNightlyRate(), currentNight);
   50	            subtotal = subtotal.add(nightPrice);
   51	            currentNight = currentNight.plusDays(1);
   52	        }
   53	        subtotal = PricingUtil.round(subtotal);
   54	
   55	        BigDecimal discount = PricingUtil.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
   56	        BigDecimal total = PricingUtil.round(subtotal.subtract(discount));
   57	
   58	        Reservation reservation = new Reservation(
   59	            reservationIdCounter.getAndIncrement(),
   60	            roomNumber,
   61	            guestName,
   62	            guestEmail,
   63	            guestCpf,
   64	            checkIn,
   65	            checkOut,
   66	            guests,
   67	            ratePlan,
   68	            nights,
   69	            subtotal,
   70	            discount,
   71	            total
   72	        );
   73	
   74	        reservations.put(reservation.getId(), reservation);
   75	        return reservation;
   76	    }
   77	
   78	    public Reservation getReservation(Long id) {
   79	        Reservation reservation = reservations.get(id);
   80	        if (reservation == null) {
   81	            throw ApiException.reservationNotFound();
   82	        }
   83	        return reservation;
   84	    }
   85	
   86	    public Reservation confirmReservation(Long id) {
