  325	    public static BigDecimal round(BigDecimal value) {
  326	        return value.setScale(2, RoundingMode.HALF_EVEN);
  327	    }
  328	
  329	    public static boolean isHighSeason(LocalDate date) {
  330	        int month = date.getMonthValue();
  331	        int day = date.getDayOfMonth();
  332	
  333	        if (month == 7) {
  334	            return true;
  335	        }
  336	
  337	        if (month == 12 && day >= 15) {
  338	            return true;
  339	        }
  340	
  341	        if (month == 1 || month == 2) {
  342	            return true;
  343	        }
  344	
  345	        return false;
  346	    }
  347	
  348	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate night) {
  349	        BigDecimal price = baseRate;
  350	        if (isHighSeason(night)) {
  351	            price = price.multiply(new BigDecimal("1.20"));
  352	        }
  353	        return round(price);
  354	    }
