   241	    public String generateOccupancyReport(LocalDate date) {
   242	        List<Reservation> reservations = reservationService.getReservationsForNight(date);
   243	
   244	        StringBuilder csv = new StringBuilder();
   245	        csv.append("room,type,reservation,check_in,check_out\n");
