   260	    public String generateRevenueReport(int year, int month) {
   261	        List<Reservation> reservations = reservationService.getReservationsForMonth(year, month);
   262	
   263	        StringBuilder csv = new StringBuilder();
   264	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   265	
   266	        BigDecimal total = BigDecimal.ZERO;
   267	
   268	        for (Reservation reservation : reservations) {
   269	            BigDecimal amount = reservation.getAmountPaid();
   270	            if (reservation.getRefund() != null) {
   271	                amount = amount.subtract(reservation.getRefund());
   272	            }
   273	
   274	            csv.append(reservation.getId()).append(",");
   275	            csv.append(reservation.getRoomNumber()).append(",");
   276	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
   277	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
   278	            csv.append(reservation.getStatus()).append(",");
   279	            csv.append(formatAmount(amount)).append("\n");
   280	
   281	            total = total.add(amount);
   282	        }
   283	
   284	        csv.append("total,").append(formatAmount(total));
   285	
   286	        return csv.toString();
   287	    }
