public class IntegrationTest {
    private static Javalin app;
    private static final int TEST_PORT = 7071;

    @BeforeAll
    public static void setUp() {
        RestAssured.port = TEST_PORT;
        RestAssured.baseURI = "http://localhost";

        System.clearProperty("HOTEL_TEST_MODE");

        MessageService messageService = new MessageService();
        RoomService roomService = new RoomService();
        ReservationService reservationService = new ReservationService(roomService, messageService);
        ReportService reportService = new ReportService(reservationService, roomService);

        RoomController roomController = new RoomController(roomService);
        ReservationController reservationController = new ReservationController(reservationService, roomService);
        MessageController messageController = new MessageController(messageService);
        ReportController reportController = new ReportController(reportService);

        ObjectMapper objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JavaTimeModule());
        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

        app = Javalin.create(config -> {
            config.jsonMapper(new JavalinJackson(objectMapper, true));
        });

        app.get("/rooms", roomController::getRooms);

        app.post("/reservations", reservationController::createReservation);
        app.get("/reservations/{id}", reservationController::getReservation);
        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
        app.post("/reservations/{id}/check-in", reservationController::checkIn);
        app.post("/reservations/{id}/check-out", reservationController::checkOut);
        app.get("/reservations/{id}/document", reservationController::getDocument);

        app.get("/messages", messageController::getMessages);

        app.get("/reports/occupancy", reportController::getOccupancyReport);
        app.get("/reports/revenue", reportController::getRevenueReport);

        app.exception(ApiException.class, (e, ctx) -> {
            ctx.status(e.getStatusCode());
            ctx.json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
        });

        app.exception(BadRequestResponse.class, (e, ctx) -> {
            ctx.status(400);
            ctx.json(new ErrorResponse("INVALID_REQUEST", "Corpo da requisição inválido"));
        });

        app.exception(Exception.class, (e, ctx) -> {
            e.printStackTrace();
            ctx.status(500);
            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Erro interno do servidor"));
        });

        app.start(TEST_PORT);
    }

    @AfterAll
    public static void tearDown() {
        if (app != null) {
            app.stop();
        }
    }

    @Test
    public void testInvalidEmailBlocked() {
        String body = """
            {
                "roomNumber": "301",
                "guestName": "Ana Paula",
                "guestEmail": "ana.gmail.com",
                "guestCpf": "99988877766",
                "checkIn": "2027-04-01",
                "checkOut": "2027-04-03",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(body)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("findAll { it.to == 'ana.gmail.com' }[0].status", is("BLOCKED"));
    }

    @Test
# Pousada Maré Alta - Sistema de Reservas

Sistema de gerenciamento de reservas desenvolvido em Java 21 com Javalin.

## Compilar e executar

### Compilar o projeto
```bash
mvn clean package
```

### Executar os testes
```bash
mvn verify
```

### Iniciar o servidor
```bash
java -jar target/reservas-1.0-SNAPSHOT.jar
```

O servidor inicia na porta 7070 por padrão. Para usar outra porta:
```bash
PORT=8080 java -jar target/reservas-1.0-SNAPSHOT.jar
```

## Modo de teste

Para ativar o modo de teste (e-mails redirecionados):
```bash
HOTEL_TEST_MODE=true java -jar target/reservas-1.0-SNAPSHOT.jar
```

## API Endpoints

### Quartos
- `GET /rooms` - Lista todos os quartos

### Reservas
- `POST /reservations` - Criar reserva
- `GET /reservations/{id}` - Consultar reserva
- `POST /reservations/{id}/confirmation` - Confirmar reserva
- `POST /reservations/{id}/cancellation` - Cancelar reserva
- `POST /reservations/{id}/check-in` - Fazer check-in
- `POST /reservations/{id}/check-out` - Fazer check-out
- `GET /reservations/{id}/document` - Segunda via do comprovante

### Mensagens
- `GET /messages` - Lista todas as mensagens enviadas

